@RunWith(RobolectricTestRunner.class)
@Config(sdk=28)
@LooperMode(LooperMode.Mode.PAUSED)
public class AndroidIntegrationTest {
 private Context context;
 @Before public void setup()throws Exception{context=RuntimeEnvironment.getApplication();context.deleteDatabase("character-catalog-v1.sqlite");new File(context.getFilesDir(),"hub-state-v1.json").delete();new File(context.getFilesDir(),"hub-state-v1.json.bak").delete();new HubStore(context).save(TestStates.twelve());}
 private String fixture(boolean duplicate)throws Exception{JSONArray a=new JSONArray();for(int i=1;i<=1001;i++)a.put(new JSONObject().put("ID",duplicate?1:i).put("アイコン",i==1001?(Object)"new_form":Integer.valueOf(i)).put("モンスター名",i==1?"検索キャラ":"試験キャラ"+i).put("略称",i==1?"ｹﾝｻｸ":"").put("属性",i==1?"火":"水").put("進化状態",i==1?"獣神化":"進化前").put("記事番号",i));return a.toString();}
 @Test public void sqliteCatalogImportAndUnifiedCustomSearch()throws Exception{try(CatalogRepository catalog=new CatalogRepository(context)){assertEquals(1001,catalog.importStream(new JsonReader(new StringReader(fixture(false)))));JSONArray custom=new JSONArray().put(new JSONObject().put("id","custom:test").put("no","").put("name","検索キャラ真").put("element","火").put("form","真獣神化"));catalog.custom(custom,new JSONArray());List<JSONObject> found=catalog.search("検索キャラ","火",Collections.emptySet(),false,0,50);assertEquals(2,found.size());assertEquals(1,catalog.search("ｹﾝｻｸ","火",Collections.emptySet(),false,0,50).size());assertEquals(1,catalog.search("検索キャラ","火",Collections.singleton("custom:test"),true,0,50).size());assertEquals(0,catalog.search("%","すべて",Collections.emptySet(),false,0,50).size());JSONObject special=catalog.search("試験キャラ1001","すべて",Collections.emptySet(),false,0,50).get(0);assertEquals("new_form",special.getString("icon"));assertEquals("",special.getString("no"));}}
 @Test public void realPublicCatalogWhenLocalFixtureIsProvided()throws Exception{String file=System.getenv("MONST_CATALOG_FIXTURE");Assume.assumeTrue(file!=null&&!file.isEmpty());try(CatalogRepository catalog=new CatalogRepository(context);JsonReader reader=new JsonReader(new InputStreamReader(new FileInputStream(file),java.nio.charset.StandardCharsets.UTF_8))){assertEquals(Integer.parseInt(System.getenv("MONST_CATALOG_COUNT")),catalog.importStream(reader));catalog.custom(new JSONArray(),new JSONArray());String expectedName;try(JsonReader check=new JsonReader(new InputStreamReader(new FileInputStream(file),java.nio.charset.StandardCharsets.UTF_8))){check.beginArray();check.beginObject();String value="";while(check.hasNext()){String key=check.nextName();if(key.equals("モンスター名"))value=check.nextString();else check.skipValue();}expectedName=value;}assertFalse(expectedName.isEmpty());List<JSONObject> first=catalog.search(expectedName,"すべて",Collections.emptySet(),false,0,50);assertTrue(first.stream().anyMatch(r->expectedName.equals(r.optString("name"))));java.util.Map<String,String> expected=new java.util.HashMap<>();try(JsonReader all=new JsonReader(new InputStreamReader(new FileInputStream(file),java.nio.charset.StandardCharsets.UTF_8))){all.beginArray();while(all.hasNext()){all.beginObject();String id="",name="";while(all.hasNext()){String key=all.nextName();if(key.equals("ID"))id="gw:"+all.nextString();else if(key.equals("モンスター名"))name=all.nextString();else all.skipValue();}all.endObject();expected.put(id,name);}all.endArray();}List<JSONObject> stored=catalog.search("","すべて",Collections.emptySet(),false,0,30000);assertEquals(expected.size(),stored.size());for(JSONObject row:stored)assertEquals(expected.get(row.getString("id")),row.getString("name"));}}
 @Test public void inventoryRecordStillSearchesAfterSourceEntryDisappears()throws Exception{try(CatalogRepository catalog=new CatalogRepository(context)){JSONObject owned=new JSONObject().put("catalog_id","gw:removed").put("name","旧キャラ").put("element","木").put("form","獣神化");catalog.custom(new JSONArray(),new JSONArray().put(owned));assertEquals(1,catalog.search("旧キャラ","木",Collections.singleton("gw:removed"),true,0,50).size());}}
 @Test public void failedImportRollsBackEntireCatalog()throws Exception{try(CatalogRepository catalog=new CatalogRepository(context)){catalog.importStream(new JsonReader(new StringReader(fixture(false))));try{catalog.importStream(new JsonReader(new StringReader(fixture(true))));fail();}catch(Exception expected){}assertEquals(1001,catalog.count());try{catalog.importStream(new JsonReader(new StringReader("[]")));fail();}catch(Exception expected){}assertEquals(1001,catalog.count());}}
 @Test public void atomicStoreRoundTripAndBadStateDoesNotReplaceSavedData()throws Exception{HubStore store=new HubStore(context);HubState s=store.load();String id=s.accounts().getJSONObject(0).getString("id");s.setOrbs(id,20,"",Instant.EPOCH);store.save(s);HubState bad=s.copy();bad.root.put("reset_hour",99);try{store.save(bad);fail();}catch(Exception expected){}assertEquals(20,store.load().totalOrbs());assertEquals(4,store.load().resetHour());}
 @Test public void homeAndManagerScreensCreateWithoutErrors()throws Exception{try(org.robolectric.android.controller.ActivityController<HubActivity> controller=Robolectric.buildActivity(HubActivity.class).setup()){HubActivity activity=controller.get();for(String page:new String[]{"home","accounts","daily","bond","orbs","urls","settings","teams","missions","goals","formations","orb_plans"}){ReflectionHelpers.callInstanceMethod(activity,"navigate",ReflectionHelpers.ClassParameter.from(String.class,page));assertNotNull(activity.findViewById(android.R.id.content));assertTrue("screen failed: "+page,org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog()==null||!org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog().isShowing());}}}
 @Test public void notificationCompletionAndTiming()throws Exception{HubState s=TestStates.twelve();JSONObject goal=new JSONObject().put("current",3).put("target",3).put("due","2026-10-20T12:00:00+09:00").put("lead_hours",24);assertTrue(DeadlineScheduler.complete(s,"goals",goal));assertEquals(Instant.parse("2026-10-19T03:00:00Z"),DeadlineScheduler.reminder(goal));assertFalse(DeadlineScheduler.complete(s,"orb_plans",new JSONObject().put("received",false)));}

 @Test public void automaticUpdateJobCanBeEnabledAndDisabled()throws Exception{HubStore store=new HubStore(context);HubState s=store.load();s.root.put("catalog_auto",true).put("catalog_unmetered",true);store.save(s);CatalogUpdates.schedule(context);android.app.job.JobScheduler jobs=(android.app.job.JobScheduler)context.getSystemService(Context.JOB_SCHEDULER_SERVICE);assertNotNull(jobs.getPendingJob(CatalogUpdates.PERIODIC));assertEquals(android.app.job.JobInfo.NETWORK_TYPE_UNMETERED,jobs.getPendingJob(CatalogUpdates.PERIODIC).getNetworkType());s.root.put("catalog_auto",false);store.save(s);CatalogUpdates.schedule(context);assertNull(jobs.getPendingJob(CatalogUpdates.PERIODIC));assertNull(jobs.getPendingJob(CatalogUpdates.ON_OPEN));}

 private android.view.View byDescription(android.view.View v,String wanted){if(wanted.equals(String.valueOf(v.getContentDescription())))return v;if(v instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)v;for(int i=0;i<group.getChildCount();i++){android.view.View found=byDescription(group.getChildAt(i),wanted);if(found!=null)return found;}}return null;}
 @Test public void catalogEntryChoosesAccountBeforeShowingCatalog()throws Exception{try(org.robolectric.android.controller.ActivityController<HubActivity> controller=Robolectric.buildActivity(HubActivity.class).setup()){HubActivity a=controller.get();ReflectionHelpers.callInstanceMethod(a,"navigate",ReflectionHelpers.ClassParameter.from(String.class,"catalog"));assertEquals("catalog_accounts",ReflectionHelpers.getField(a,"page"));ReflectionHelpers.callInstanceMethod(a,"openCatalogFor",ReflectionHelpers.ClassParameter.from(String.class,""));assertEquals("catalog",ReflectionHelpers.getField(a,"page"));assertEquals("",ReflectionHelpers.getField(a,"accountFilter"));}}
 @Test public void gridButtonsEditSelectedAccountAndGlobalViewKeepsCombinedCount()throws Exception{HubStore store=new HubStore(context);HubState s=store.load();String main=s.accounts().getJSONObject(0).getString("id"),sub=s.accounts().getJSONObject(1).getString("id");JSONObject c=new JSONObject().put("id","custom:test").put("name","テスト").put("element","火").put("form","進化前").put("no","").put("icon","").put("article","");s.planner().put("custom_characters",c);s.planner().adjustOwned(c,sub,1);store.save(s);try(org.robolectric.android.controller.ActivityController<HubActivity> controller=Robolectric.buildActivity(HubActivity.class).setup()){HubActivity a=controller.get();ReflectionHelpers.setField(a,"page","catalog");ReflectionHelpers.setField(a,"accountFilter",main);ReflectionHelpers.setField(a,"catalogRows",java.util.Collections.singletonList(c));ReflectionHelpers.callInstanceMethod(a,"render");android.view.View plus=byDescription(a.findViewById(android.R.id.content),"メインのテストを1体増やす");assertNotNull(plus);plus.performClick();assertEquals(1,store.load().planner().owned("custom:test",main));assertEquals(1,store.load().planner().owned("custom:test",sub));ReflectionHelpers.setField(a,"accountFilter","");ReflectionHelpers.callInstanceMethod(a,"render");assertNull(byDescription(a.findViewById(android.R.id.content),"メインのテストを1体増やす"));assertEquals(2,store.load().planner().owned("custom:test",""));}}
 @Test public void existingCatalogSchemaGetsIconColumnWithoutDataLoss()throws Exception{java.io.File path=context.getDatabasePath("character-catalog-v1.sqlite");path.getParentFile().mkdirs();try(android.database.sqlite.SQLiteDatabase old=android.database.sqlite.SQLiteDatabase.openOrCreateDatabase(path,null)){old.execSQL("CREATE TABLE characters(id TEXT PRIMARY KEY,no TEXT NOT NULL,name TEXT NOT NULL,alias TEXT NOT NULL,element TEXT NOT NULL,form TEXT NOT NULL,search TEXT NOT NULL,article TEXT NOT NULL)");old.execSQL("INSERT INTO characters VALUES('gw:1','1','旧キャラ','','火','進化','旧きゃら','1')");}try(CatalogRepository catalog=new CatalogRepository(context)){catalog.custom(new JSONArray(),new JSONArray());assertEquals(1,catalog.count());JSONObject r=catalog.search("旧キャラ","すべて",Collections.emptySet(),false,0,50).get(0);assertEquals("旧キャラ",r.getString("name"));assertEquals("",r.getString("icon"));}}
 @Test public void emptyFirstInstallCanOpenAccountPicker()throws Exception{new HubStore(context).save(HubState.create());try(org.robolectric.android.controller.ActivityController<HubActivity> controller=Robolectric.buildActivity(HubActivity.class).setup()){HubActivity a=controller.get();ReflectionHelpers.callInstanceMethod(a,"navigate",ReflectionHelpers.ClassParameter.from(String.class,"catalog"));assertEquals("catalog_accounts",ReflectionHelpers.getField(a,"page"));assertEquals(0,new HubStore(context).load().accounts().length());assertTrue(org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog()==null||!org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog().isShowing());}}

 private void go(HubActivity a,String p){ReflectionHelpers.callInstanceMethod(a,"navigate",ReflectionHelpers.ClassParameter.from(String.class,p));}
 private void catalogFor(HubActivity a,String id){ReflectionHelpers.callInstanceMethod(a,"openCatalogFor",ReflectionHelpers.ClassParameter.from(String.class,id));}
 @Test public void backReturnsThroughCatalogAndAccountSelection()throws Exception{try(org.robolectric.android.controller.ActivityController<HubActivity> c=Robolectric.buildActivity(HubActivity.class).setup()){HubActivity a=c.get();String id=new HubStore(context).load().accounts().getJSONObject(0).getString("id");go(a,"catalog");catalogFor(a,id);ReflectionHelpers.setField(a,"catalogQuery","検索");ReflectionHelpers.setField(a,"catalogDraft","検索中");ReflectionHelpers.setField(a,"catalogOwned",true);catalogFor(a,"");a.onBackPressed();assertEquals("catalog",ReflectionHelpers.getField(a,"page"));assertEquals(id,ReflectionHelpers.getField(a,"accountFilter"));assertEquals("検索",ReflectionHelpers.getField(a,"catalogQuery"));assertEquals("検索中",ReflectionHelpers.getField(a,"catalogDraft"));assertEquals(Boolean.TRUE,ReflectionHelpers.getField(a,"catalogOwned"));a.onBackPressed();assertEquals("catalog_accounts",ReflectionHelpers.getField(a,"page"));a.onBackPressed();assertEquals("home",ReflectionHelpers.getField(a,"page"));assertFalse(a.isFinishing());a.onBackPressed();assertTrue(a.isFinishing());}}
 @Test public void explicitHomeClearsBackHistory(){try(org.robolectric.android.controller.ActivityController<HubActivity> c=Robolectric.buildActivity(HubActivity.class).setup()){HubActivity a=c.get();go(a,"daily");go(a,"settings");a.onBackPressed();assertEquals("daily",ReflectionHelpers.getField(a,"page"));go(a,"home");a.onBackPressed();assertTrue(a.isFinishing());}}
 @Test public void backHistorySurvivesActivityRecreation()throws Exception{try(org.robolectric.android.controller.ActivityController<HubActivity> c=Robolectric.buildActivity(HubActivity.class).setup()){HubActivity a=c.get();go(a,"catalog");catalogFor(a,new HubStore(context).load().accounts().getJSONObject(0).getString("id"));c.recreate();a=c.get();assertEquals("catalog",ReflectionHelpers.getField(a,"page"));a.onBackPressed();assertEquals("catalog_accounts",ReflectionHelpers.getField(a,"page"));a.onBackPressed();assertEquals("home",ReflectionHelpers.getField(a,"page"));}}
 @Test @Config(sdk=35) public void modernBackDispatcherUsesPreviousScreen(){try(org.robolectric.android.controller.ActivityController<HubActivity> c=Robolectric.buildActivity(HubActivity.class).setup()){HubActivity a=c.get();go(a,"daily");ReflectionHelpers.callInstanceMethod(a,"goBack");assertEquals("home",ReflectionHelpers.getField(a,"page"));assertFalse(a.isFinishing());}}
}
